listPrivateEmployeeTestDialogs:
listPrivateEmployeeTestDialogs: tool({
  description:
    "Показать владельцу список его личных тестовых диалогов сотрудника. Возвращает даты, идентификаторы, версии и наличие предложения без переписки.",
  inputSchema: privateEmployeeInput,
  execute: async ({ employeeId }) =>
    (
      await (
        await import("./private-employee-chat.server")
      ).loadPrivateEmployeeChats(employeeId)
    ).history,
}),

proposeApprovePrivateTestRule:
proposeApprovePrivateTestRule: tool({
  description:
    "Предложить владельцу утвердить уже запрошенное правило из личного теста. Используй версию и действующий идентификатор конкретного диалога. Правило начнёт действовать только после подтверждения.",
  inputSchema: privateDialogVersion,
  execute: async (input) => {
    const rule = await (
      await import("./private-employee-chat.server")
    ).privateEmployeeRuleProposal(input);
    const summary = "Сохранить правило из личного теста: " + rule;
    ctx.propose({ tool: "approvePrivateEmployeeRule", summary, input: { ...input, rule } });
    return { proposed: summary };
  },
}),
